// Appendix A of docs/spec/modernize-ado.md, transcribed as data. These facts
// fill the missing retired majors; no spec or filesystem access occurs at runtime.
var legacyInputs = func() map[string][]catalog.Input {
 var rows map[string][]catalog.Input
 if err := json.Unmarshal([]byte(legacyInputJSON), &rows); err != nil { panic(err) }
 return rows
}()

func oldTaskVersion(cat *catalog.Catalog, ref string) *catalog.TaskVersion {
 for name, inputs := range legacyInputs {
  if strings.EqualFold(name, ref) { return &catalog.TaskVersion{Inputs: inputs} }
 }
 return taskVersion(cat, ref)
}

